mapper.insert:

    SELECT SEQ_COMPANY_DOCUMENTS.NEXTVAL FROM DUAL

INSERT INTO COMPANY_DOCUMENTS (
    ID, DOC_TYPE, DOC_NUMBER, TITLE, REVISION_NO, REVISION_DATE,
    DOC_OWNER, FILE_LINK, NOTE, TAGS, CREATED_AT, UPDATED_AT
) VALUES (
    #{id}, #{docType}, #{docNumber}, #{title}, #{revisionNo}, #{revisionDate},
    #{owner}, #{fileLink}, #{note, jdbcType=CLOB}, #{tags}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT FROM COMPANY_DOCUMENTS
DOC_TYPE = #{docType}
ORDER BY TITLE

SELECT FROM COMPANY_DOCUMENTS WHERE ID IN
#{id}
ORDER BY TITLE

SELECT m.DOCUMENT_ID, l.NAME AS LAW_NAME FROM DOC_LAW_MAPPINGS m JOIN TRACKED_LAWS l ON l.ID = m.TRACKED_LAW_ID WHERE m.DOCUMENT_ID IN
#{id}
ORDER BY m.DOCUMENT_ID, l.NAME

SELECT DISTINCT tg.TAG, l.ID AS LAW_ID FROM (
SELECT CAST(#{tag} AS VARCHAR(512)) AS TAG FROM DUAL
) tg CROSS JOIN TRACKED_LAWS l LEFT JOIN SCRAPED_LAW_CONTENTS c ON c.SOURCE_TYPE = l.SOURCE_TYPE AND c.EXTERNAL_ID = l.EXTERNAL_ID WHERE l.IS_ACTIVE = 1 AND ( INSTR(l.NAME, tg.TAG) > 0 OR (c.CONTENT IS NOT NULL AND DBMS_LOB.INSTR(c.CONTENT, tg.TAG) > 0) )
